import{_ as l,r as t,o as i,c as u,e,a as s,s as p,d as a}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Трейты - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Манипуляция атрибутами","slug":"манипуляция-атрибутами","link":"#манипуляция-атрибутами","children":[{"level":3,"title":"Nullable","slug":"nullable","link":"#nullable","children":[]},{"level":3,"title":"Hashable","slug":"hashable","link":"#hashable","children":[]},{"level":3,"title":"Purgeable","slug":"purgeable","link":"#purgeable","children":[]},{"level":3,"title":"Encryptable","slug":"encryptable","link":"#encryptable","children":[]},{"level":3,"title":"Sluggable","slug":"sluggable","link":"#sluggable","children":[]}]},{"level":2,"title":"Сортировка и упорядочивание","slug":"сортировка-и-упорядочивание","link":"#сортировка-и-упорядочивание","children":[{"level":3,"title":"Sortable","slug":"sortable","link":"#sortable","children":[]},{"level":3,"title":"Simple Tree","slug":"simple-tree","link":"#simple-tree","children":[{"level":4,"title":"Отображение","slug":"отображение","link":"#отображение","children":[]}]},{"level":3,"title":"Nested Tree","slug":"nested-tree","link":"#nested-tree","children":[{"level":4,"title":"Создание корневого узла","slug":"создание-корневого-узла","link":"#создание-корневого-узла","children":[]},{"level":4,"title":"Вставка узлов","slug":"вставка-узлов","link":"#вставка-узлов","children":[]},{"level":4,"title":"Удаление узлов","slug":"удаление-узлов","link":"#удаление-узлов","children":[]},{"level":4,"title":"Получение уровня вложенности узла","slug":"получение-уровня-вложенности-узла","link":"#получение-уровня-вложенности-узла","children":[]},{"level":4,"title":"Перемещение узлов","slug":"перемещение-узлов","link":"#перемещение-узлов","children":[]}]}]},{"level":2,"title":"Служебные функции","slug":"служебные-функции","link":"#служебные-функции","children":[{"level":3,"title":"Валидация","slug":"валидация","link":"#валидация","children":[{"level":4,"title":"Расширенные правила валидации","slug":"расширенные-правила-валидации","link":"#расширенные-правила-валидации","children":[]},{"level":4,"title":"Получение ошибок валидации","slug":"получение-ошибок-валидации","link":"#получение-ошибок-валидации","children":[]},{"level":4,"title":"Переопределение валидации","slug":"переопределение-валидации","link":"#переопределение-валидации","children":[]},{"level":4,"title":"Пользовательские сообщения об ошибках","slug":"пользовательские-сообщения-об-ошибках","link":"#пользовательские-сообщения-об-ошибках","children":[]},{"level":4,"title":"Пользовательские имена атрибутов","slug":"пользовательские-имена-атрибутов","link":"#пользовательские-имена-атрибутов","children":[]},{"level":4,"title":"Динамические правила валидации","slug":"динамические-правила-валидации","link":"#динамические-правила-валидации","children":[]},{"level":4,"title":"Пользовательские правила валидации","slug":"пользовательские-правила-валидации","link":"#пользовательские-правила-валидации","children":[]}]},{"level":3,"title":"Мягкое удаление","slug":"мягкое-удаление","link":"#мягкое-удаление","children":[{"level":4,"title":"Запросы к мягко удалённым моделям","slug":"запросы-к-мягко-удаленным-моделям","link":"#запросы-к-мягко-удаленным-моделям","children":[]},{"level":4,"title":"Окончательное удаление моделей","slug":"окончательное-удаление-моделеи","link":"#окончательное-удаление-моделеи","children":[]},{"level":4,"title":"Мягкое удаление связей","slug":"мягкое-удаление-связеи","link":"#мягкое-удаление-связеи","children":[]},{"level":4,"title":"Включение мягко удалённых связей","slug":"включение-мягко-удаленных-связеи","link":"#включение-мягко-удаленных-связеи","children":[]}]},{"level":3,"title":"Мультисайт","slug":"мультисаит","link":"#мультисаит","children":[{"level":4,"title":"Принудительная синхронизация","slug":"принудительная-синхронизация","link":"#принудительная-синхронизация","children":[]},{"level":4,"title":"Сохранение моделей","slug":"сохранение-моделеи","link":"#сохранение-моделеи","children":[]}]},{"level":3,"title":"Revisionable","slug":"revisionable","link":"#revisionable","children":[]}]}],"relativePath":"3.x/ru/extend/database/traits.md","filePath":"3.x/ru/extend/database/traits.md"}'),r={name:"3.x/ru/extend/database/traits.md"};function k(d,n,g,h,v,b){const o=t("pre-heading"),c=t("post-heading");return i(),u("div",null,[e(o),n[0]||(n[0]=s("h1",null,"Трейты",-1)),e(c),n[1]||(n[1]=p(`<p>Трейты моделей используются для реализации общей функциональности.</p><h2 id="манипуляция-атрибутами"><a href="#манипуляция-атрибутами" class="header-anchor">#</a> Манипуляция атрибутами</h2><h3 id="nullable"><a href="#nullable" class="header-anchor">#</a> Nullable</h3><p>Nullable-атрибуты устанавливаются в <code>NULL</code>, когда оставлены пустыми. Для обнуления атрибутов в вашей модели примените трейт <code>October\\Rain\\Database\\Traits\\Nullable</code> и объявите свойство <code>$nullable</code> с массивом, содержащим атрибуты для обнуления.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Nullable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$nullable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;sku&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="hashable"><a href="#hashable" class="header-anchor">#</a> Hashable</h3><p>Хешируемые атрибуты хешируются сразу при первом присваивании значения атрибуту модели. Для хеширования атрибутов в вашей модели примените трейт <code>October\\Rain\\Database\\Traits\\Hashable</code> и объявите свойство <code>$hashable</code> с массивом, содержащим атрибуты для хеширования.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Hashable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$hashable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;password&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="purgeable"><a href="#purgeable" class="header-anchor">#</a> Purgeable</h3><p>Очищаемые атрибуты не будут сохранены в базу данных при создании или обновлении модели. Для очистки атрибутов в вашей модели примените трейт <code>October\\Rain\\Database\\Traits\\Purgeable</code> и объявите свойство <code>$purgeable</code> с массивом, содержащим атрибуты для очистки.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Purgeable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$purgeable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;password_confirmation&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Используйте метод <code>getOriginalPurgeValue</code>, чтобы получить значение, которое было очищено после сохранения модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">getOriginalPurgeValue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;password_confirmation&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Альтернативно используйте метод <code>restorePurgedValues</code> для восстановления всех очищенных значений.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">restorePurgedValues</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="encryptable"><a href="#encryptable" class="header-anchor">#</a> Encryptable</h3><p>Аналогично трейту <code>Hashable</code>, зашифрованные атрибуты шифруются при установке, но также расшифровываются при получении атрибута. Для шифрования атрибутов в вашей модели примените трейт <code>October\\Rain\\Database\\Traits\\Encryptable</code> и объявите свойство <code>$encryptable</code> с массивом, содержащим атрибуты для шифрования.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Encryptable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$encryptable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;api_secret&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block warning"><p>Зашифрованные атрибуты несовместимы с <a href="./../system/models.html">jsonable-атрибутами</a>.</p></div><h3 id="sluggable"><a href="#sluggable" class="header-anchor">#</a> Sluggable</h3><p>Слаги — это осмысленные коды, которые обычно используются в URL страниц. Для автоматической генерации уникального слага для вашей модели примените трейт <code>October\\Rain\\Database\\Traits\\Sluggable</code> и объявите свойство <code>$slugs</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sluggable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$slugs</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Свойство <code>$slugs</code> должно быть массивом, где ключ — это целевой столбец для слага, а значение — исходная строка, используемая для генерации слага. В приведённом выше примере, если столбец <code>name</code> был установлен в <strong>Cheyenne</strong>, в результате столбец <code>slug</code> будет установлен в <strong>cheyenne</strong>, <strong>cheyenne-2</strong>, или <strong>cheyenne-3</strong> и т.д. перед созданием модели.</p><p>Для генерации слага из нескольких источников передайте другой массив в качестве исходного значения:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$slugs</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;last_name&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Слаги генерируются только при первом создании модели. Чтобы переопределить или отключить эту функциональность, просто установите атрибут slug вручную:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Remy&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;custom-slug&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Slug will not be generated</span>
</code></pre></div><p>Используйте метод <code>slugAttributes</code> для повторной генерации слагов при обновлении модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">slugAttributes</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="сортировка-и-упорядочивание"><a href="#сортировка-и-упорядочивание" class="header-anchor">#</a> Сортировка и упорядочивание</h2><h3 id="sortable"><a href="#sortable" class="header-anchor">#</a> Sortable</h3><p>Сортируемые модели хранят числовое значение в <code>sort_order</code>, которое поддерживает порядок сортировки каждой отдельной модели в коллекции. Для добавления столбца <code>sort_order</code> в вашу таблицу используйте метод <code>integer</code> внутри миграции.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;sort_order&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">default</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для хранения порядка сортировки для ваших моделей примените трейт <code>October\\Rain\\Database\\Traits\\Sortable</code> и убедитесь, что ваша схема имеет определённый столбец для его использования.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sortable</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы можете изменить имя ключа, используемого для идентификации порядка сортировки, определив константу <code>SORT_ORDER</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">SORT_ORDER</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_sort_order_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Используйте метод <code>setSortableOrder</code> для установки порядка для нескольких записей. Массив содержит идентификаторы моделей в том порядке сортировки, в котором они должны отображаться.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">setSortableOrder</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>При сортировке подмножества записей второй массив используется для предоставления справочного пула значений порядка сортировки. Например, следующий код назначает столбцу порядка сортировки значения 100, 200 или 300.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">setSortableOrder</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">200</span><span class="token punctuation">,</span> <span class="token number">300</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="simple-tree"><a href="#simple-tree" class="header-anchor">#</a> Simple Tree</h3><p>Модель простого дерева использует столбец <code>parent_id</code> для поддержания отношений родитель-потомок между моделями. Для добавления столбца <code>parent_id</code> в вашу таблицу используйте метод <code>integer</code> внутри миграции.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для использования простого дерева примените трейт <code>October\\Rain\\Database\\Traits\\SimpleTree</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SimpleTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Этот трейт автоматически внедрит две <a href="./relations.html">связи модели</a> с именами <code>parent</code> и <code>children</code>, что является эквивалентом следующих определений.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;parent&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name static-context">Category</span> <span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;children&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name static-context">Category</span> <span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Вам не нужно определять эти связи самостоятельно, однако вы можете изменить имя ключа, используемого для идентификации родителя, определив константу <code>PARENT_ID</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">const</span> <span class="token constant">PARENT_ID</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;my_parent_column&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Коллекции моделей, использующих этот трейт, будут возвращать тип <code>October\\Rain\\Database\\TreeCollection</code>, который добавляет метод <code>toNested</code>. Для построения жадно загруженной древовидной структуры верните записи с жадно загруженными связями.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">toNested</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="отображение"><a href="#отображение" class="header-anchor">#</a> Отображение</h4><p>Для отображения всех уровней элементов и их потомков вы можете использовать рекурсивную обработку</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">macro</span> renderChildren<span class="token punctuation">(</span>item<span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> item<span class="token punctuation">.</span>children <span class="token operator">is</span> <span class="token operator">not</span> empty <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> child <span class="token operator">in</span> item<span class="token punctuation">.</span>children <span class="token delimiter punctuation">%}</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token punctuation">.</span>name <span class="token delimiter punctuation">}}</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> _self_<span class="token punctuation">.</span>renderChildren<span class="token punctuation">(</span>child<span class="token punctuation">)</span><span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endmacro</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">import</span> _self as nav <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> nav<span class="token punctuation">.</span>renderChildren<span class="token punctuation">(</span>category<span class="token punctuation">)</span><span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h3 id="nested-tree"><a href="#nested-tree" class="header-anchor">#</a> Nested Tree</h3>`,56)),n[2]||(n[2]=s("p",null,[s("a",{href:"https://en.wikipedia.org/wiki/Nested_set_model",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Модель вложенных множеств"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])]),a(" — это продвинутая техника поддержания иерархий между моделями с использованием столбцов "),s("code",null,"parent_id"),a(", "),s("code",null,"nest_left"),a(", "),s("code",null,"nest_right"),a(" и "),s("code",null,"nest_depth"),a(". Для добавления этих столбцов в вашу таблицу используйте эти методы внутри миграции.")],-1)),n[3]||(n[3]=p(`<div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;parent_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;nest_left&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;nest_right&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;nest_depth&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для использования модели вложенных множеств примените трейт <code>October\\Rain\\Database\\Traits\\NestedTree</code>. Все возможности трейта <code>SimpleTree</code> изначально доступны в этой модели.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>NestedTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="создание-корневого-узла"><a href="#создание-корневого-узла" class="header-anchor">#</a> Создание корневого узла</h4><p>По умолчанию все узлы создаются как корневые:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$root</span> <span class="token operator">=</span> <span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Root category&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Альтернативно вам может понадобиться преобразовать существующий узел в корневой:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">makeRoot</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете обнулить его столбец <code>parent_id</code>, что работает так же, как <code>makeRoot</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token property">parent_id</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>
<span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="вставка-узлов"><a href="#вставка-узлов" class="header-anchor">#</a> Вставка узлов</h4><p>Вы можете вставлять новые узлы напрямую через связь:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child1</span> <span class="token operator">=</span> <span class="token variable">$root</span><span class="token operator">-&gt;</span><span class="token function">children</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Child 1&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Или используйте метод <code>makeChildOf</code> для существующих узлов:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child2</span> <span class="token operator">=</span> <span class="token class-name static-context">Category</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Child 2&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$child2</span><span class="token operator">-&gt;</span><span class="token function">makeChildOf</span><span class="token punctuation">(</span><span class="token variable">$root</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="удаление-узлов"><a href="#удаление-узлов" class="header-anchor">#</a> Удаление узлов</h4><p>Когда узел удаляется методом <code>delete</code>, все потомки узла также будут удалены. Обратите внимание, что <a href="./../system/models.html">события модели</a> delete не будут вызваны для дочерних моделей.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$child1</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="получение-уровня-вложенности-узла"><a href="#получение-уровня-вложенности-узла" class="header-anchor">#</a> Получение уровня вложенности узла</h4><p>Метод <code>getLevel</code> вернёт текущий уровень вложенности, или глубину, узла.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 0 when root</span>
<span class="token variable">$node</span><span class="token operator">-&gt;</span><span class="token function">getLevel</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre></div><h4 id="перемещение-узлов"><a href="#перемещение-узлов" class="header-anchor">#</a> Перемещение узлов</h4><p>Существует несколько методов для перемещения узлов:</p><ul><li><code>moveLeft()</code>: Найти левого соседа и переместить левее него.</li><li><code>moveRight()</code>: Найти правого соседа и переместить правее него.</li><li><code>moveBefore($otherNode)</code>: Переместить узел левее ...</li><li><code>moveAfter($otherNode)</code>: Переместить узел правее ...</li><li><code>makeChildOf($otherNode)</code>: Сделать узел дочерним для ...</li><li><code>makeRoot()</code>: Сделать текущий узел корневым.</li></ul><h2 id="служебные-функции"><a href="#служебные-функции" class="header-anchor">#</a> Служебные функции</h2><h3 id="валидация"><a href="#валидация" class="header-anchor">#</a> Валидация</h3><p>Модели October CMS используют встроенный <a href="./../services/validation.html">класс Validator</a>. Правила валидации определяются в классе модели как свойство с именем <code>$rules</code>, и класс должен использовать трейт <code>October\\Rain\\Database\\Traits\\Validation</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;between:4,16&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;alpha_num&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;between:4,8&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;confirmed&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;password_confirmation&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;alpha_num&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;between:4,8&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы также можете использовать <a href="./../services/validation.html">синтаксис массивов</a> для правил валидации.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;links.*.url&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;url&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;links.*.anchor&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Модели валидируются автоматически при вызове метода <code>save</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Actual Person&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">email</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;a.person@example.tld&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">password</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;passw0rd&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// Returns false if model is invalid</span>
<span class="token variable">$success</span> <span class="token operator">=</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Вы также можете валидировать модель в любое время с помощью метода <code>validate</code>.</p></div><h4 id="расширенные-правила-валидации"><a href="#расширенные-правила-валидации" class="header-anchor">#</a> Расширенные правила валидации</h4><p>Правило валидации <code>unique</code> автоматически настраивается и не требует указания имени таблицы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;unique&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Правило валидации <code>required</code> поддерживает модификаторы <strong>create</strong> и <strong>update</strong> для применения только при создании или обновлении модели соответственно. Следующее правило требуется только когда модель ещё не существует.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required:create&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="получение-ошибок-валидации"><a href="#получение-ошибок-валидации" class="header-anchor">#</a> Получение ошибок валидации</h4><p>Когда модель не проходит валидацию, объект <code>Illuminate\\Support\\MessageBag</code> прикрепляется к модели. Объект содержит сообщения об ошибках валидации. Получите экземпляр коллекции сообщений об ошибках валидации с помощью метода <code>errors</code> или свойства <code>$validationErrors</code>. Получите все ошибки валидации с помощью <code>errors()-&gt;all()</code>. Получите ошибки для <em>конкретного</em> атрибута с помощью <code>validationErrors-&gt;get(&#39;attribute&#39;)</code>.</p><div class="custom-block tip"><p>Модель использует объект <code>MessagesBag</code>, который имеет <a href="./../services/validation.html">простой и элегантный метод</a> форматирования ошибок.</p></div><h4 id="переопределение-валидации"><a href="#переопределение-валидации" class="header-anchor">#</a> Переопределение валидации</h4><p>Метод <code>forceSave</code> валидирует модель и сохраняет независимо от того, есть ли ошибки валидации.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>

<span class="token comment">// Creates a user without validation</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">forceSave</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="пользовательские-сообщения-об-ошибках"><a href="#пользовательские-сообщения-об-ошибках" class="header-anchor">#</a> Пользовательские сообщения об ошибках</h4><p>Как и класс Validator, вы можете устанавливать пользовательские сообщения об ошибках, используя <a href="./../services/validation.html">тот же синтаксис</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$customMessages</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The :attribute field is required.&#39;</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы также можете добавлять пользовательские сообщения об ошибках к синтаксису массивов для правил валидации.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;links.*.url&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;url&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;links.*.anchor&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$customMessages</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;links.*.url.required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The url is required&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;links.*.url.*&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The url needs to be a valid url&#39;</span>
        <span class="token string single-quoted-string">&#39;links.*.anchor.required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The anchor text is required&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>В приведённом выше примере вы можете писать пользовательские сообщения об ошибках для конкретных правил валидации (здесь мы использовали: <code>required</code>). Или вы можете использовать <code>*</code> для выбора всего остального (здесь мы добавили пользовательское сообщение к правилу валидации <code>url</code> с помощью <code>*</code>).</p><h4 id="пользовательские-имена-атрибутов"><a href="#пользовательские-имена-атрибутов" class="header-anchor">#</a> Пользовательские имена атрибутов</h4><p>Вы также можете задать пользовательские имена атрибутов с помощью массива <code>$attributeNames</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$attributeNames</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Email Address&#39;</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="динамические-правила-валидации"><a href="#динамические-правила-валидации" class="header-anchor">#</a> Динамические правила валидации</h4><p>Вы можете применять правила динамически, переопределив метод <a href="./../system/models.html">события модели</a> <code>beforeValidate</code>. Здесь мы проверяем, является ли атрибут <code>is_remote</code> равным <code>false</code>, и затем динамически устанавливаем атрибуты <code>latitude</code> и <code>longitude</code> как обязательные поля.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeValidate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">is_remote</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">rules</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;latitude&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">;</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">rules</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;longitude&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="пользовательские-правила-валидации"><a href="#пользовательские-правила-валидации" class="header-anchor">#</a> Пользовательские правила валидации</h4><p>Вы также можете создавать пользовательские правила валидации <a href="./../services/validation.html">тем же способом</a>, что и для сервиса <code>Validator</code>.</p><h3 id="мягкое-удаление"><a href="#мягкое-удаление" class="header-anchor">#</a> Мягкое удаление</h3><p>При мягком удалении модель фактически не удаляется из базы данных. Вместо этого в записи устанавливается временная метка <code>deleted_at</code>. Для включения мягкого удаления модели примените трейт <code>October\\Rain\\Database\\Traits\\SoftDelete</code> к модели и добавьте столбец deleted_at в ваше свойство <code>$dates</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SoftDelete</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$dates</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;deleted_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Для добавления столбца <code>deleted_at</code> в вашу таблицу используйте метод <code>softDeletes</code> из миграции:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">softDeletes</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Теперь, когда вы вызываете метод <code>delete</code> на модели, столбец <code>deleted_at</code> будет установлен в текущую временную метку. При запросе модели, использующей мягкое удаление, «удалённые» модели не будут включены в результаты запроса.</p><p>Для определения, была ли данная модель мягко удалена, используйте метод <code>trashed</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">trashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="запросы-к-мягко-удаленным-моделям"><a href="#запросы-к-мягко-удаленным-моделям" class="header-anchor">#</a> Запросы к мягко удалённым моделям</h4><h5>Включение мягко удалённых моделей</h5><p>Как отмечено выше, мягко удалённые модели автоматически исключаются из результатов запроса. Однако вы можете принудительно включить мягко удалённые модели в набор результатов, используя метод <code>withTrashed</code> в запросе:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>withTrashed</code> также может использоваться в запросе <a href="./relations.html">связи</a>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">history</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h5>Получение только мягко удалённых моделей</h5><p>Метод <code>onlyTrashed</code> получит <strong>только</strong> мягко удалённые модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">onlyTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h5>Восстановление мягко удалённых моделей</h5><p>Иногда вам может понадобиться «отменить удаление» мягко удалённой модели. Для восстановления мягко удалённой модели в активное состояние используйте метод <code>restore</code> на экземпляре модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете использовать метод <code>restore</code> в запросе для быстрого восстановления нескольких моделей:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Restore a single model instance...</span>
<span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Restore all related models...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="окончательное-удаление-моделеи"><a href="#окончательное-удаление-моделеи" class="header-anchor">#</a> Окончательное удаление моделей</h4><p>Иногда вам может понадобиться действительно удалить модель из базы данных. Для окончательного удаления мягко удалённой модели из базы данных используйте метод <code>forceDelete</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Force deleting a single model instance...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">forceDelete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Force deleting all related models...</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">forceDelete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="мягкое-удаление-связеи"><a href="#мягкое-удаление-связеи" class="header-anchor">#</a> Мягкое удаление связей</h4><p>Когда две связанные модели имеют включённое мягкое удаление, вы можете каскадировать событие удаления, определив опцию <code>softDelete</code> в <a href="./relations.html">определении связи</a>. В этом примере, если модель пользователя мягко удалена, комментарии, принадлежащие этому пользователю, также будут мягко удалены.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SoftDelete</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;softDelete&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>Если связанная модель не использует трейт мягкого удаления, она будет обработана так же, как опция <code>delete</code>, и удалена окончательно.</p></div><p>При тех же условиях, когда первичная модель восстанавливается, все связанные модели, использующие опцию <code>softDelete</code>, также будут восстановлены.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Restore the user and comments</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">restore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="включение-мягко-удаленных-связеи"><a href="#включение-мягко-удаленных-связеи" class="header-anchor">#</a> Включение мягко удалённых связей</h4><p>Мягко удалённые записи не включаются в результаты поиска связей, однако вы можете включить их, добавив область <code>withTrashed</code> к запросу.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;comments&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Comment</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;scope&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;withTrashed&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="мультисаит"><a href="#мультисаит" class="header-anchor">#</a> Мультисайт</h3><p>При применении мультисайта к модели доступны только записи, принадлежащие активному сайту. Активный сайт привязывается к столбцу <code>site_id</code>, установленному в записи. Для включения мультисайта для модели примените трейт <code>October\\Rain\\Database\\Traits\\Multisite</code> и определите атрибуты для распространения по всем записям с помощью свойства <code>$propagatable</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Multisite</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$propagatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;api_code&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>Свойство <code>$propagatable</code> требуется трейтом мультисайта, но может быть оставлено пустым массивом для отключения распространения любого атрибута.</p></div><p>Для добавления столбца <code>site_id</code> в вашу таблицу используйте метод <code>integer</code> из миграции. Столбец <code>site_root_id</code> также может использоваться для связывания записей вместе через корневую запись.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_root_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Теперь, когда запись создаётся, она будет назначена активному сайту, и переключение на другой сайт автоматически распространит новую запись. При обновлении записи распространяемые поля копируются в каждую запись, принадлежащую корневой записи.</p><h4 id="принудительная-синхронизация"><a href="#принудительная-синхронизация" class="header-anchor">#</a> Принудительная синхронизация</h4><p>В некоторых случаях все записи должны существовать для каждого сайта, например, категории и теги. Вы можете принудительно создать каждую запись на всех сайтах, установив свойство <code>$propagatableSync</code> в true, которое по умолчанию равно false. После включения, после сохранения модели, она создаст ту же модель для других сайтов, если они ещё не существуют.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$propagatableSync</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
</code></pre></div><p>При использовании <a href="./../../cms/resources/multisite.html">групп сайтов</a> записи будут распространяться на все сайты в этой группе. Это можно контролировать, установив свойство <code>$propagatableSync</code> в массив с параметрами конфигурации.</p><div class="table"><table tabindex="0"><thead><tr><th>Параметр</th><th>Описание</th></tr></thead></table></div><ul><li><strong>sync</strong> - логика синхронизации конкретных сайтов, доступные варианты: <code>all</code>, <code>group</code>, <code>locale</code>. По умолчанию: <code>group</code></li><li><strong>delete</strong> - удалять все связанные записи при удалении любой записи, по умолчанию: <code>true</code></li><li><strong>except</strong> - предоставляет имена атрибутов, которые не должны реплицироваться для вновь синхронизированных записей</li></ul><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$propagatableSync</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;sync&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;all&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;delete&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;except&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;description&#39;</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="сохранение-моделеи"><a href="#сохранение-моделеи" class="header-anchor">#</a> Сохранение моделей</h4><p>Модели, сохранённые с трейтом мультисайта, не распространяются по умолчанию. Используйте метод <code>savePropagate</code>, чтобы убедиться, что правила распространения вступят в силу.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">savePropagate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="revisionable"><a href="#revisionable" class="header-anchor">#</a> Revisionable</h3><p>Модели October CMS могут записывать историю изменений значений, сохраняя ревизии. Для хранения ревизий вашей модели примените трейт <code>October\\Rain\\Database\\Traits\\Revisionable</code> и объявите свойство <code>$revisionable</code> с массивом, содержащим атрибуты для отслеживания изменений. Вам также необходимо определить <code>$morphMany</code> <a href="./relations.html">связь модели</a> с именем <code>revision_history</code>, которая ссылается на класс <code>System\\Models\\Revision</code> с именем <code>revisionable</code> — здесь хранятся данные истории ревизий.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Revisionable</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$revisionable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$morphMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;revision_history&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Revision</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;revisionable&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>По умолчанию хранится максимум 500 записей, однако это можно изменить, объявив свойство <code>$revisionableLimit</code> в модели с новым значением лимита.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var int revisionableLimit as the maximum number records to keep.
 */</span>
<span class="token keyword">public</span> <span class="token variable">$revisionableLimit</span> <span class="token operator">=</span> <span class="token number">8</span><span class="token punctuation">;</span>
</code></pre></div><p>К истории ревизий можно обращаться как к любой другой связи:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$history</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">revision_history</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$history</span> <span class="token keyword">as</span> <span class="token variable">$record</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">field</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39; updated &#39;</span><span class="token punctuation">;</span>
    <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;from &#39;</span> <span class="token operator">.</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">old_value</span><span class="token punctuation">;</span>
    <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;to &#39;</span> <span class="token operator">.</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">new_value</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Запись ревизии опционально поддерживает связь с пользователем через атрибут <code>user_id</code>. Вы можете включить метод <code>getRevisionableUser</code> в вашу модель для отслеживания пользователя, внёсшего изменение.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getRevisionableUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">getUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,118))])}const y=l(r,[["render",k]]);export{f as __pageData,y as default};
